const notificationBody=n=>completedApproval(n)?'이 요청의 승인 처리가 완료됐습니다. 현재 운용 상태를 확인하세요.':displayText(n.body);
const labels={INFO:'안내',WAITING_EVIDENCE:'검증 대기',APPROVAL_READY:'최종 승인 대기',COMPLETED:'완료',FAILED:'확인 필요'};
