 function sync(){if(disposed)return;const n=items.filter(i=>!i.readAt&&!i.expired).length;for(const b of window.document.querySelectorAll('.app-notification-button[data-app-notifications]')){b.setAttribute('aria-label','알림'+(n?' · 읽지 않음 '+n+'개':''));const badge=b.querySelector('[data-notification-count]');if(badge){badge.textContent=String(n);badge.hidden=!n;}}}
 function button(){return '<button type="button" class="shell-control app-notification-button" data-app-notifications aria-label="알림" title="알림"><svg class="app-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg><span class="app-notification-count" data-notification-count hidden></span></button>';}
 const controls=()=>'<div class="actions"><button type="button" class="button" data-notification-push'+(!supported()||pending?' disabled':'')+'>'+(pushCleanupId?'서버 연결 정리 재시도':pushEnabled?'이 기기 푸시 끄기':'휴대폰 알림 켜기')+'</button>'+(pushEnabled?'<button type="button" class="button" data-notification-test>테스트 알림</button>':'')+'</div><p class="tiny muted">'+(pushCleanupId?'이 기기의 푸시는 꺼졌습니다. 서버 연결 정보 정리가 남았습니다.':pushOffConfirmed?'이 기기 푸시는 꺼져 있습니다. 앱 알림함과 운용은 유지됩니다.':!supported()?'휴대폰에서 비공개 HTTPS 앱을 열어 알림을 연결하세요.':Notification.permission==='denied'?'브라우저 사이트 설정에서 VIV의 알림을 허용하세요.':pushEnabled?'앱을 닫아도 푸시를 받습니다. 승인 요청은 알림의 승인 버튼 한 번으로 확정하고, 내용을 누르면 앱에서 확인합니다.':'처음 한 번 알림을 허용하면 이 휴대폰에 연결됩니다.')+'</p>'+(pushError?'<p class="error-text" role="alert">'+esc(pushError)+'</p>':'');
