 const savedChangeMarkup=()=>listNeedsRefresh?'<p role="status">알림 변경은 저장됐습니다. 최신 목록을 다시 불러오세요.</p>':'';
 const loadFailureMarkup=(id='')=>savedChangeMarkup()+'<div class="mind-operation-attention notification-load-error"><p role="alert">'+esc(loadError)+'</p><button type="button" class="button" data-app-notifications data-notification-refresh="'+esc(id)+'">다시 불러오기</button></div>';
