  const toolbar='<div class="notification-toolbar"><div class="studio-local-tabs" role="group" aria-label="알림 보기"><button type="button" class="button" data-notification-view="active" aria-pressed="'+(inboxView==='active')+'">알림함</button><button type="button" class="button" data-notification-view="requests" aria-pressed="'+(inboxView==='requests')+'">요청 ('+items.filter(needsAttention).length+')</button><button type="button" class="button" data-notification-view="trash" aria-pressed="'+(inboxView==='trash')+'">휴지통'+(deletedItems.length?' ('+deletedItems.length+')':'')+'</button></div></div>'+(!loading&&cleanup?'<div class="actions notification-cleanup" role="group" aria-label="알림 정리">'+cleanup+'</div>':'');
  const search='<div class="notification-search"><label class="field"><span class="sr-only">알림 검색</span><input type="search" data-notification-query value="'+esc(inboxQuery)+'" placeholder="제목·내용 검색" autocomplete="off"'+(loading?' disabled':'')+'></label><button type="button" class="button" data-notification-query-clear hidden>검색 해제</button><output class="tiny muted" data-notification-search-count aria-live="polite" hidden></output></div>';
