  const readError=readErrorMarkup(id);
  open(n.title,(approvalErrorId===n.id?errorMarkup():'')+'<article data-context-entity="notification" data-context-id="'+esc(n.id)+'" data-entity-name="'+esc(n.title)+'"><p role="status">'+notificationStatus(n)+'</p>'+detailBody+readError+(n.status==='WAITING_EVIDENCE'?'<p>최종 승인 요청이 준비되면 이 알림함으로 안내합니다.</p>':'')+(approvalError&&approvalRecovery&&approvalErrorId===n.id||n.expired?recovery(n):'')+contextActions(n)+'</article>','<button class="button" data-app-notifications>알림함</button>'+(!n.deletedAt?approveButton(n):'')+(completedApproval(n)?recovery(n,'운용 상태 보기'):'')+(n.reportId?'<a class="button" href="'+esc(brokerageReportExportPath(n.reportId))+'" target="_blank" rel="noopener">운용보고서 보기</a>':'')+(n.documentId?'<button class="button" data-notification-document="'+esc(n.documentId)+'">연결 자료 보기</button>':''));
