 async function refresh(){if(disposed)return;const generation=++refreshGeneration;try{const data=await request();if(generation!==refreshGeneration)return;items=data.items;deletedItems=data.deletedItems??[];publicKey=data.publicKey;loadError='';listNeedsRefresh=false;sync();}catch(e){if(generation===refreshGeneration)loadError=e.message;}}
